package catalog

import "errors"

// Product is a sellable item.
type Product struct {
	ID   string
	SKU  string
	Name string
}

// ErrNotFound reports a lookup that matched nothing.
var ErrNotFound = errors.New("product not found")

// Catalog is an in-memory product list.
type Catalog struct {
	products []Product
}

// New builds a Catalog from products.
func New(products []Product) Catalog {
	return Catalog{products: products}
}

// FindByID returns the product with the given ID.
func (c Catalog) FindByID(id string) (Product, error) {
	return c.find(func(p Product) bool { return p.ID == id })
}

// FindBySKU returns the product with the given SKU.
func (c Catalog) FindBySKU(sku string) (Product, error) {
	return c.find(func(p Product) bool { return p.SKU == sku })
}

func (c Catalog) find(matches func(Product) bool) (Product, error) {
	for _, product := range c.products {
		if matches(product) {
			return product, nil
		}
	}
	return Product{}, ErrNotFound
}

