package catalog

import "testing"

func sampleCatalog() Catalog {
	return New([]Product{
		{ID: "1", SKU: "PEN-BLK", Name: "Black Pen"},
		{ID: "2", SKU: "PAD-A4", Name: "A4 Pad"},
	})
}

func TestFindByIDReturnsMatch(t *testing.T) {
	product, err := sampleCatalog().FindByID("2")
	if err != nil || product.Name != "A4 Pad" {
		t.Fatalf("FindByID = %+v, %v", product, err)
	}
}

func TestFindBySKUReportsMissing(t *testing.T) {
	if _, err := sampleCatalog().FindBySKU("NOPE"); err != ErrNotFound {
		t.Fatalf("err = %v, want ErrNotFound", err)
	}
}
